import glob
import json
import os
import re
import struct

print("=== RECYCLE BIN $I metadata (original paths) ===")
for ip in glob.glob(r"C:\$Recycle.Bin\*\$I*"):
    try:
        raw = open(ip, "rb").read()
        # $I header: version(8) size(8) filetime(8) then utf16le path (v2: length at offset 24)
        name = None
        if len(raw) > 28:
            try:
                vlen = struct.unpack_from("<q", raw, 24)[0]
                name = raw[32 : 32 + vlen * 2].decode("utf-16le", "replace")
            except Exception:
                name = None
        if not name:
            name = raw.decode("utf-16le", "ignore").strip("\x00")
        print(f"{os.path.basename(ip):16s} mtime={__import__('datetime').datetime.fromtimestamp(os.path.getmtime(ip))} -> {name[:160]}")
    except Exception as e:
        print(ip, "ERR", e)

print()
