        target = real_by_title.get(item["title"])
        if target is None:
            kept.append(item)
            continue
        if item["user_story_id"] and not target["user_story_id"]:
            target["user_story_id"] = item["user_story_id"]

    for index, item in enumerate(kept, 1):
        item["req_id"] = f"R-{index:03d}"
    return kept

