"""Derive development order from (data flow U workflow) and compare with the WBS table."""
import io
import re
import collections

LINK = re.compile(r"^\s*(?!\)\s*$)(\S.*?)\s*(-->|-\.->)\s*(?:\|([^|]*)\|)?\s*(\S.*?)\s*$")

edges = []
for ln in io.open("epi-dev-slices-overview.mmd", encoding="utf-8"):
    if ln.strip().startswith("%%"):
        continue
    m = LINK.match(ln)
    if m and not m.group(1).startswith(("LG", "LR")):
        edges.append((m.group(1), m.group(4)))

adj = collections.defaultdict(set)
for a, b in edges:
    adj[a].add(b)
nodes = {a for a, _ in edges} | {b for _, b in edges}

# --- iterative Tarjan SCC -------------------------------------------------
num, low, st, on, scc = {}, {}, [], set(), []
counter = 0
for root in sorted(nodes):
    if root in num:
        continue
    stack = [(root, iter(adj[root]))]
    num[root] = low[root] = counter
    counter += 1
    st.append(root)
    on.add(root)
    while stack:
        v, it = stack[-1]
        advanced = False
        for w in it:
            if w not in num:
                num[w] = low[w] = counter
                counter += 1
                st.append(w)
                on.add(w)
                stack.append((w, iter(adj[w])))
                advanced = True
                break
            if w in on:
                low[v] = min(low[v], num[w])
        if advanced:
            continue
        stack.pop()
        if stack:
            low[stack[-1][0]] = min(low[stack[-1][0]], low[v])
        if low[v] == num[v]:
            comp = []
            while True:
                w = st.pop()
                on.discard(w)
                comp.append(w)
                if w == v:
                    break
            scc.append(comp)

cyclic = [c for c in scc if len(c) > 1]
print(f"节点 {len(nodes)} | 边 {len(edges)} | SCC {len(scc)} 个，含环 {len(cyclic)} 个")
for c in cyclic:
    print("  环:", " ".join(sorted(c)))

# --- condensed DAG -> longest-path levels = derived development order -----
comp_of = {v: i for i, c in enumerate(scc) for v in c}
dadj = collections.defaultdict(set)
for a, b in edges:
    if comp_of[a] != comp_of[b]:
        dadj[comp_of[a]].add(comp_of[b])

indeg = collections.Counter()
for u, vs in dadj.items():
    for v in vs:
        indeg[v] += 1
level = [0] * len(scc)
queue = [i for i in range(len(scc)) if indeg[i] == 0]
seen = 0
while queue:
    u = queue.pop(0)
    seen += 1
    for v in dadj[u]:
        level[v] = max(level[v], level[u] + 1)
        indeg[v] -= 1
        if indeg[v] == 0:
            queue.append(v)
print(f"\n缩点 DAG 可拓扑排序: {seen == len(scc)} | 层数 {max(level) + 1 if scc else 0}")

by_level = collections.defaultdict(list)
for i, c in enumerate(scc):
    by_level[level[i]].append("{" + ",".join(sorted(c)) + "}" if len(c) > 1 else c[0])
print("\n=== 推导出的开发顺序（同层 = 互相依赖，必须一起开工或先钉接口）===")
for lv in sorted(by_level):
    print(f"  L{lv}: " + "  ".join(sorted(by_level[lv])))

# --- compare with the WBS table's documented development dependencies -----
md = io.open("epi-dev-slices-overview.md", encoding="utf-8").read()
doc = {}
for row in re.findall(r"^\| (S\d\d) \|.*$", md, re.M):
    line = next(l for l in md.splitlines() if l.startswith(f"| {row} |"))
    cells = [c.strip() for c in line.strip("|").split("|")]
    doc[row] = set(re.findall(r"S\d\d", cells[3]))

direct = collections.defaultdict(set)
for a, b in edges:
    direct[b].add(a)

print("\n=== 文档「开发依赖」列 vs 图推导（只看 S 开头的切片间依赖）===")
only_doc, only_graph = [], []
for s in sorted(doc):
    d, g = doc[s], {a for a in direct[s] if re.fullmatch(r"S\d\d", a)}
    if d - g:
        only_doc.append(f"{s}: 文档有图无 {sorted(d - g)}")
    if g - d:
        only_graph.append(f"{s}: 图有文档无 {sorted(g - d)}")
print(f"  文档写了但图里没有: {len(only_doc)}")
for x in only_doc:
    print("   ", x)
print(f"  图里有但文档没写: {len(only_graph)}")
for x in only_graph:
    print("   ", x)

