"""Guard the slice-overview diagram: style indices, edge taxonomy, derived order.

The diagram used to carry 133 hand-written `linkStyle` lines for 82 links: 50
indices were assigned twice, the later one won, and 37 solid edges rendered
orange. Nothing failed - the picture just lied. It also mixed three relations
(development order, data flow, control flow) into two line styles, which forced
13 duplicate edges and left a third of the edges mis-styled.

These tests pin the replacement invariants:
  * every link is styled exactly once, colour matches its class
  * the class is derivable from the line style, and ?-prefixed edges are purple
  * DATA edges are acyclic except for the one declared agent-loop cycle
"""

import collections
import re
from pathlib import Path

import pytest

DESIGN = Path(__file__).resolve().parents[1] / "agent-design"
MMD = DESIGN / "epi-dev-slices-overview.mmd"
MD = DESIGN / "epi-dev-slices-overview.md"

BLUE = "#2563EB"      # solid  -> DATA: the edge carries content
ORANGE = "#F97316"    # dashed -> WORKFLOW: the edge carries a decision
PURPLE = "#A855F7"    # dashed -> UNCERTAIN: content and decision, not ruled on

# The agent loop is a genuine data cycle: context -> task list -> state machine
# -> current phase back into context. Anything else that becomes a data cycle is
# a decision smuggled into a data pipe.
DECLARED_DATA_CYCLES = [frozenset({"S17", "S18", "S19"})]

LINK = re.compile(r"^\s*(?!\)\s*$)(\S.*?)\s*(-->|-\.->)\s*(?:\|([^|]*)\|)?\s*(\S.*?)\s*$")
STYLE = re.compile(r"^\s*linkStyle\s+(\d+)\s+stroke:(#[0-9A-Fa-f]{6})")
LEGEND = ("LGS", "LRS", "LPU")


@pytest.fixture(scope="module")
def lines() -> list[str]:
    return MMD.read_text(encoding="utf-8").splitlines()


def links(lines):
    """Every link line in declaration order: (source, label, target, arrow)."""
    out = []
    for line in lines:
        if line.strip().startswith("%%"):
            continue
        m = LINK.match(line)
        if m:
            out.append((m.group(1), (m.group(3) or "").strip(), m.group(4), m.group(2)))
    return out


def style_map(lines):
    styles = {}
    for line in lines:
        m = STYLE.match(line.strip())
        if m:
            styles[int(m.group(1))] = m.group(2)
    return styles


def classify(lines):
    """Edge class taken from the colour, i.e. from the rendered picture."""
    styles = style_map(lines)
    out = []
    for i, (a, label, b, arrow) in enumerate(links(lines)):
        if a.startswith(LEGEND):
            continue
        colour = styles.get(i)
        kind = {BLUE: "DATA", ORANGE: "WORKFLOW", PURPLE: "UNCERTAIN"}.get(colour)
        out.append((a, label, b, arrow, kind))
    return out


def test_no_duplicate_linkstyle_index(lines):
    seen, dup = set(), []
    for line in lines:
        m = STYLE.match(line.strip())
        if m:
            if m.group(1) in seen:
                dup.append(m.group(1))
            seen.add(m.group(1))
    assert not dup, f"linkStyle 索引被重复赋值，后者覆盖前者：{dup}"


def test_every_link_is_styled(lines):
    styles = style_map(lines)
    missing = [i for i in range(len(links(lines))) if i not in styles]
    assert not missing, f"{len(missing)} 条 link 没有显式配色，会退回 default：{missing}"


def test_colour_and_arrow_agree(lines):
    bad = []
    for a, _label, _b, arrow, kind in classify(lines):
        if kind is None:
            bad.append((a, "unknown colour"))
        elif kind == "DATA" and arrow != "-->":
            bad.append((a, "DATA must be solid"))
        elif kind in ("WORKFLOW", "UNCERTAIN") and arrow != "-.->":
            bad.append((a, f"{kind} must be dashed"))
    assert not bad, f"配色与线型不符：{bad}"


def test_uncertain_edges_are_marked_with_question(lines):
    unmarked = [f"{a}->{b}:{label}" for a, label, b, _arrow, kind in classify(lines)
                if kind == "UNCERTAIN" and not label.startswith("？")]
    assert not unmarked, f"待定边必须以 ？ 开头，否则读者会当成已裁定：{unmarked}"
    mislabelled = [f"{a}->{b}:{label}" for a, label, b, _arrow, kind in classify(lines)
                   if label.startswith("？") and kind != "UNCERTAIN"]
    assert not mislabelled, f"带 ？ 但配色不是待定色：{mislabelled}"


def test_no_duplicate_relations(lines):
    """Same (source, target) may repeat only if the classes differ."""
    seen = collections.defaultdict(list)
    for a, label, b, _arrow, kind in classify(lines):
        seen[(a, b, kind)].append(label)
    dup = {k: v for k, v in seen.items() if len(v) > 1}
    assert not dup, f"同一关系画了多次：{dup}"


def test_data_flow_cycles_are_declared(lines):
    adj = collections.defaultdict(set)
    for a, _label, b, _arrow, kind in classify(lines):
        if kind == "DATA":
            adj[a].add(b)
    nodes = set(adj) | {b for vs in adj.values() for b in vs}

    index, low, stack, onstack, comps = {}, {}, [], set(), []
    for root in sorted(nodes):
        if root in index:
            continue
        work = [(root, iter(adj[root]))]
        index[root] = low[root] = len(index)
        stack.append(root)
        onstack.add(root)
        while work:
            v, it = work[-1]
            moved = False
            for w in it:
                if w not in index:
                    index[w] = low[w] = len(index)
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, iter(adj[w])))
                    moved = True
                    break
                if w in onstack:
                    low[v] = min(low[v], index[w])
            if moved:
                continue
            work.pop()
            if work:
                low[work[-1][0]] = min(low[work[-1][0]], low[v])
            if low[v] == index[v]:
                comp = []
                while True:
                    w = stack.pop()
                    onstack.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                comps.append(frozenset(comp))

    found = sorted((c for c in comps if len(c) > 1), key=sorted)
    assert found == sorted(DECLARED_DATA_CYCLES, key=sorted), (
        f"数据流出现未声明的环。已声明 {sorted(map(sorted, DECLARED_DATA_CYCLES))}，"
        f"实际 {sorted(map(sorted, found))}。环=有人把决策塞进了数据管道，"
        f"或者该边的归类需要重新裁定。"
    )


def test_legend_shows_all_three_classes(lines):
    assert any("subgraph Legend" in line for line in lines), "图例缺失"
    legend = [(a, arrow) for a, _l, _b, arrow in links(lines) if a.startswith(LEGEND)]
    assert legend == [("LGS", "-->"), ("LRS", "-.->"), ("LPU", "-.->")], (
        f"图例必须示范 数据流/工作流/待定 三种线型，实际 {legend}"
    )


def test_markdown_block_matches_standalone_file():
    block = re.search(r"```mermaid\n(.*?)\n```", MD.read_text(encoding="utf-8"), re.S).group(1)
    assert block.strip() == MMD.read_text(encoding="utf-8").strip(), (
        "epi-dev-slices-overview.md 内嵌的图与 .mmd 不一致，改图要同时改两处"
    )

"""Generate a self-contained interactive HTML graph from the slice overview.

Source of truth stays the .mmd. This only renders it, plus the development level
derived from DATA edges. No external assets - embedded desks are usually offline.

    python tools/gen_slices_graph.py           # write epi-dev-slices-graph.html
    python tools/gen_slices_graph.py --check   # fail if the html is stale

Interactions: click a node to isolate its upstream/downstream, buttons switch
direction / depth / edge class, drag to pan, wheel to zoom.
"""

import collections
import json
import re
import sys
from pathlib import Path

DESIGN = Path(__file__).resolve().parents[1]
MMD = DESIGN / "epi-dev-slices-overview.mmd"
MD = DESIGN / "epi-dev-slices-overview.md"
OUT = DESIGN / "epi-dev-slices-graph.html"

LINK = re.compile(r"^\s*(?!\)\s*$)(\S.*?)\s*(-->|-\.->)\s*(?:\|([^|]*)\|)?\s*(\S.*?)\s*$")
STYLE = re.compile(r"^\s*linkStyle\s+(\d+)\s+stroke:(#[0-9A-Fa-f]{6})")
COLOUR = {"#2563eb": "data", "#f97316": "flow", "#a855f7": "open"}
NAME = {"data": "数据流", "flow": "工作流", "open": "待定"}


def parse():
    lines = MMD.read_text(encoding="utf-8").splitlines()
    styles = {}
    for ln in lines:
        m = STYLE.match(ln.strip())
        if m:
            styles[int(m.group(1))] = m.group(2).lower()
    edges, i = [], -1
    for ln in lines:
        if ln.strip().startswith("%%"):
            continue
        m = LINK.match(ln)
        if not m:
            continue
        i += 1
        src = m.group(1).split("[", 1)[0]
        if src.startswith(("LGS", "LRS", "LPU")):
            continue
        kind = COLOUR.get(styles.get(i, ""), "").upper().lower()
        edges.append({"s": src, "t": m.group(4),
                      "label": (m.group(3) or "").strip(), "kind": kind})

    titles = {}
    for ln in MD.read_text(encoding="utf-8").splitlines():
        m = re.match(r"^\| (S\d\d) \| ([^|]+) \| ([^|]+) \|", ln)
        if m:
            titles[m.group(1)] = (m.group(2).strip(), m.group(3).strip())
    return edges, titles


def levels(edges):
    """Development level = longest path over DATA edges, SCC-condensed."""
    data = [(e["s"], e["t"]) for e in edges if e["kind"] == "data"]
    adj = collections.defaultdict(set)
    for a, b in data:
        adj[a].add(b)
    nodes = {a for a, _ in data} | {b for _, b in data}
    index, low, stack, onstack, comps = {}, {}, [], set(), []
    for root in sorted(nodes):
        if root in index:
            continue
        work = [(root, iter(adj[root]))]
        index[root] = low[root] = len(index)
        stack.append(root)
        onstack.add(root)
        while work:
            v, it = work[-1]
            moved = False
            for w in it:
                if w not in index:
                    index[w] = low[w] = len(index)
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, iter(adj[w])))
                    moved = True
                    break
                if w in onstack:
                    low[v] = min(low[v], index[w])
            if moved:
                continue
            work.pop()
            if work:
                low[work[-1][0]] = min(low[work[-1][0]], low[v])
            if low[v] == index[v]:
                comp = []
                while True:
                    w = stack.pop()
                    onstack.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                comps.append(comp)
    comp_of = {v: i for i, c in enumerate(comps) for v in c}
    dag = collections.defaultdict(set)
    indeg = collections.Counter()
    for a, b in data:
        u, v = comp_of[a], comp_of[b]
        if u != v and v not in dag[u]:
            dag[u].add(v)
            indeg[v] += 1
    lvl = [0] * len(comps)
    q = [i for i in range(len(comps)) if indeg[i] == 0]
    while q:
        u = q.pop(0)
        for v in sorted(dag[u]):
            lvl[v] = max(lvl[v], lvl[u] + 1)
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    return {v: lvl[comp_of[v]] for v in nodes}, {v: c for c in comps for v in c}


def build():
    edges, titles = parse()
    nodes = sorted({e["s"] for e in edges} | {e["t"] for e in edges})
    lvl, comp = levels(edges)
    by_level = collections.defaultdict(list)
    for n in nodes:
        by_level[lvl.get(n, 0)].append(n)
    pos = {}
    for lv, group in sorted(by_level.items()):
        for i, n in enumerate(sorted(group, key=lambda x: (not x.startswith("S"), x))):
            pos[n] = (lv, i)
    cyc = collections.Counter(tuple(sorted(c)) for c in comp.values())
    payload = {
        "nodes": [{"id": n, "x": pos[n][0], "y": pos[n][1], "level": lvl.get(n, 0),
                   "name": titles.get(n, ("", ""))[0], "output": titles.get(n, ("", ""))[1],
                   "loop": len(cyc[tuple(sorted({m for m, c in comp.items() if c == comp[n]}))]) > 1}
                  for n in nodes],
        "edges": edges,
        "names": NAME,
    }
    return payload


