 button.on{background:#0F172A;color:#fff;border-color:#0F172A}
 #hint{color:#64748B} #info{position:fixed;right:12px;top:56px;width:270px;background:#fff
      border:1px solid #E2E8F0;border-radius:8px;padding:10px;display:none;z-index:2}
 #info h3{margin:0 0 4px;font-size:14px} #info table{width:100%;border-collapse:collapse;font-size:12px}
 #info td{padding:2px 0;vertical-align:top} #info td.k{color:#64748B;width:58px}
 svg{display:block;cursor:grab} .dim{opacity:.08} .edge .lbl{font-size:10px;fill:#475569}
 .node rect{stroke-width:1.6px;rx:6} .node text{font-size:12px;font-weight:600;fill:#0F172A}
 .node{cursor:pointer} .lv{fill:#94A3B8;font-size:11px;font-weight:700}
</style></head><body>
<div id=bar>
  <b>EPI 切片依赖图</b>
