  <span>深度</span>
  <button data-k=1>1</button><button data-k=2>2</button><button data-k=99 class=on>全部</button>
  <span>类别</span>
  <label><input type=checkbox data-c=data checked> 数据流</label>
  <label><input type=checkbox data-c=flow checked> 工作流</label>
