<script>
const D = __DATA__;
const COL = {data:'#2563EB', flow:'#F97316', open:'#A855F7'};
const SX=230, SY=64, W=150, H=40;
let dir='both', depth=99, on={data:1,flow:1,open:1}, focus=null, tx=60, ty=70, sc=1;
const svg=document.getElementById('svg'), NS='http://www.w3.org/2000/svg';
const byId=Object.fromEntries(D.nodes.map(n=>[n.id,n]));
const out={}, inn={};
D.edges.forEach(e=>{(out[e.s]=out[e.s]||[]).push(e);(inn[e.t]=inn[e.t]||[]).push(e);});

function reach(start, direction){
  const seen={[start]:0}, q=[[start,0]], adj=direction==='up'?inn:out;
  while(q.length){const [n,d]=q.shift(); if(d>=depth) continue;
    for(const e of (adj[n]||[])){ if(!on[e.kind]) continue;
      const m=direction==='up'?e.s:e.t;
      if(seen[m]===undefined){seen[m]=d+1;q.push([m,d+1]);} } }
  return seen;
}
function el(t,a){const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);return e;}

function draw(){
  svg.innerHTML='';
  const g=el('g',{transform:`translate(${tx},${ty}) scale(${sc})`}); svg.appendChild(g);
  const keep = focus ? reach(focus, dir) : null;
