                   && keep[e.s]<=keep[e.t] || (dir==='up'&&keep[e.t]!==undefined&&keep[e.s]!==undefined));
    const x1=a.x*SX+W, y1=a.y*SY+H/2, x2=b.x*SX, y2=b.y*SY+H/2;
