    g.appendChild(p);
    const t=el('text',{x:mx,y:(y1+y2)/2-4,'text-anchor':'middle',class:'lbl'});
    if(keep&&!keepThis) t.setAttribute('class','lbl dim');
    t.textContent=e.label; g.appendChild(t);
