    g2.onclick=ev=>{ev.stopPropagation();focus=focus===n.id?null:n.id;info();draw();};
    g.appendChild(g2);
  });

  const defs=el('defs',{}); g.appendChild(defs);
  for(const k in COL){
    const m=el('marker',{id:'a'+k,viewBox:'0 0 10 10',refX:9,refY:5,markerWidth:6,
      markerHeight:6,orient:'auto'});
    m.appendChild(el('path',{d:'M0,0 L10,5 L0,10 z',fill:COL[k]})); defs.appendChild(m);
  }
  svg.setAttribute('width',innerWidth); svg.setAttribute('height',Math.max(innerHeight,
    (Math.max(...D.nodes.map(n=>n.y))+2)*SY+120));
}
function info(){
  const box=document.getElementById('info');
  if(!focus){box.style.display='none';return;}
  const n=byId[focus], k=reach(focus,dir);
  const list=d=>Object.keys(k).filter(x=>k[x]===d&&x!==focus).sort().join(' ')||'—';
  const step=dir==='up'?'上游':'下游';
  box.style.display='block';
  box.innerHTML=`<h3>${focus} ${n.name||''}</h3><table>
    <tr><td class=k>目标产物</td><td>${n.output||'—'}</td></tr>
    <tr><td class=k>开发层级</td><td>L${n.level}${n.loop?' · 在数据环内（须与同环切片一起设计）':''}</td></tr>
    <tr><td class=k>${step}1跳</td><td>${list(1)}</td></tr>
    <tr><td class=k>${step}2跳</td><td>${list(2)}</td></tr>
    <tr><td class=k>合计</td><td>${Object.keys(k).length-1} 个节点</td></tr></table>`;
}
document.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{dir=b.dataset.d;
  document.querySelectorAll('[data-d]').forEach(x=>x.classList.toggle('on',x===b));draw();});
document.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>{depth=+b.dataset.k;
  document.querySelectorAll('[data-k]').forEach(x=>x.classList.toggle('on',x===b));draw();});
document.querySelectorAll('[data-c]').forEach(b=>b.onchange=()=>{on[b.dataset.c]=b.checked?1:0;draw();});
document.getElementById('reset').onclick=()=>{focus=null;tx=60;ty=70;sc=1;info();draw();};
