svg.onmousedown=e=>{drag=[e.clientX-tx,e.clientY-ty];svg.style.cursor='grabbing';};
onmouseup=()=>{drag=null;svg.style.cursor='grab';};
onmousemove=e=>{if(drag){tx=e.clientX-drag[0];ty=e.clientY-drag[1];draw();}};
svg.onwheel=e=>{e.preventDefault();sc=Math.min(2.5,Math.max(.3,sc*(e.deltaY<0?1.12:.9)));draw();};
onresize=draw; draw();
</script></body></html>
"""


def main() -> None:
    html = HTML.replace("__DATA__", json.dumps(build(), ensure_ascii=False))
    if "--check" in sys.argv:
        if not OUT.exists() or OUT.read_text(encoding="utf-8") != html:
            raise SystemExit("epi-dev-slices-graph.html 已过期，重跑 tools/gen_slices_graph.py")
        print("graph html up to date")
        return
    OUT.write_text(html, encoding="utf-8")
    print(f"wrote {OUT.name}")


if __name__ == "__main__":
    main()

