"""Generate a self-contained interactive HTML graph from the slice overview.

Source of truth stays ``epi-dev-slices-overview.mmd``. This script only renders
it, plus the development level derived from DATA edges. No external assets and no
CDN - embedded desks are usually offline. The output opens by double-click.

Usage (run anywhere, paths are resolved relative to this file):

    python agent-design/tools/gen_slices_graph.py             # write the html
    python agent-design/tools/gen_slices_graph.py --check     # fail if html is stale
    python agent-design/tools/gen_slices_graph.py --open      # write and open

Workflow after editing the diagram: edit the .mmd -> run tools/restyle_slices_overview.py
if you added/removed edges -> run this script -> pytest.

Interactions: click a node to isolate its upstream/downstream, buttons switch
direction / depth / edge class, drag to pan, wheel to zoom, Esc or a click on the
background clears the focus.
"""

import argparse
import collections
import json
import os
import re
import sys
from pathlib import Path

DESIGN = Path(__file__).resolve().parents[1]
MMD = DESIGN / "epi-dev-slices-overview.mmd"
MD = DESIGN / "epi-dev-slices-overview.md"
OUT = DESIGN / "epi-dev-slices-graph.html"

LINK = re.compile(r"^\s*(?!\)\s*$)(\S.*?)\s*(-->|-\.->)\s*(?:\|([^|]*)\|)?\s*(\S.*?)\s*$")
STYLE = re.compile(r"^\s*linkStyle\s+(\d+)\s+stroke:(#[0-9A-Fa-f]{6})")
COLOUR = {"#2563eb": "data", "#f97316": "flow", "#a855f7": "open"}
NAME = {"data": "数据流", "flow": "工作流", "open": "待定"}
LEGEND_IDS = ("LGS", "LRS", "LPU")

SX, SY, W, H = 250, 66, 152, 42


# --------------------------------------------------------------------------- #
# parse
# --------------------------------------------------------------------------- #
def parse():
    if not MMD.exists():
        raise SystemExit(f"找不到 {MMD}")
    lines = MMD.read_text(encoding="utf-8").splitlines()

    styles, dup = {}, []
    for ln in lines:
        m = STYLE.match(ln.strip())
        if m:
            i = int(m.group(1))
            if i in styles:
                dup.append(i)
            styles[i] = m.group(2).lower()
    if dup:
        raise SystemExit(f"linkStyle 索引重复 {sorted(set(dup))}，先跑 tools/restyle_slices_overview.py")

    edges, i, unstyled = [], -1, []
    for ln in lines:
        if ln.strip().startswith("%%"):
            continue
        m = LINK.match(ln)
        if not m:
            continue
        i += 1
        src = m.group(1).split("[", 1)[0]
        if src.startswith(LEGEND_IDS):
            continue
        kind = COLOUR.get(styles.get(i, ""))
        if kind is None:
            unstyled.append(f"{src} -> {m.group(4)} (linkStyle {i})")
            continue
        edges.append({"s": src, "t": m.group(4), "label": (m.group(3) or "").strip(), "kind": kind})
    if unstyled:
        raise SystemExit("这些边没有可识别的配色，先跑 tools/restyle_slices_overview.py：\n  "
                         + "\n  ".join(unstyled))

    titles = {}
    for ln in MD.read_text(encoding="utf-8").splitlines():
        m = re.match(r"^\| (S\d\d) \| ([^|]+) \| ([^|]+) \|", ln)
        if m:
            titles[m.group(1)] = (m.group(2).strip(), m.group(3).strip())
    return edges, titles


# --------------------------------------------------------------------------- #
# layout: development level (DATA only, SCC condensed) + barycentre ordering
# --------------------------------------------------------------------------- #
def data_levels(edges):
    data = [(e["s"], e["t"]) for e in edges if e["kind"] == "data"]
    adj = collections.defaultdict(set)
    for a, b in data:
        adj[a].add(b)
    nodes = {a for a, _ in data} | {b for _, b in data}

    index, low, stack, onstack, comps = {}, {}, [], set(), []
    for root in sorted(nodes):
        if root in index:
            continue
        work = [(root, iter(adj[root]))]
        index[root] = low[root] = len(index)
        stack.append(root)
        onstack.add(root)
        while work:
            v, it = work[-1]
            moved = False
            for w in it:
                if w not in index:
                    index[w] = low[w] = len(index)
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, iter(adj[w])))
                    moved = True
                    break
                if w in onstack:
                    low[v] = min(low[v], index[w])
            if moved:
                continue
            work.pop()
            if work:
                low[work[-1][0]] = min(low[work[-1][0]], low[v])
            if low[v] == index[v]:
                comp = []
                while True:
                    w = stack.pop()
                    onstack.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                comps.append(comp)

    comp_of = {v: i for i, c in enumerate(comps) for v in c}
    dag, indeg = collections.defaultdict(set), collections.Counter()
    for a, b in data:
        u, v = comp_of[a], comp_of[b]
        if u != v and v not in dag[u]:
            dag[u].add(v)
            indeg[v] += 1
    lvl = [0] * len(comps)
    q = [i for i in range(len(comps)) if indeg[i] == 0]
    while q:
        u = q.pop(0)
        for v in sorted(dag[u]):
            lvl[v] = max(lvl[v], lvl[u] + 1)
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    size = collections.Counter(comp_of.values())
    return ({v: lvl[comp_of[v]] for v in nodes},
            {v: i for v, i in comp_of.items()},
            {v for v, i in comp_of.items() if size[i] > 1})


def order_within_levels(by_level, edges):
    """Barycentre sweep: fewer edge crossings than alphabetical order."""
    levels = sorted(by_level)
    pos = {n: i for l in levels for i, n in enumerate(by_level[l])}
    up = collections.defaultdict(list)
    down = collections.defaultdict(list)
    for e in edges:
        down[e["s"]].append(e["t"])
        up[e["t"]].append(e["s"])

    def sweep(order_of_levels, neighbours):
        for l in order_of_levels:
            def key(n):
                refs = [pos[m] for m in neighbours[n] if m in pos and m not in by_level[l]]
                return (sum(refs) / len(refs) if refs else pos[n], n)
            by_level[l].sort(key=key)
            for i, n in enumerate(by_level[l]):
                pos[n] = i

    for _ in range(4):
        sweep(levels[1:], up)
        sweep(list(reversed(levels))[:-1], down)
    return pos


def build():
    edges, titles = parse()
    nodes = sorted({e["s"] for e in edges} | {e["t"] for e in edges})
    lvl, comp, loop = data_levels(edges)
    by_level = collections.defaultdict(list)
    for n in nodes:
        by_level[lvl.get(n, 0)].append(n)
    for l in by_level:
        by_level[l].sort(key=lambda x: (not x.startswith("S"), x))
    pos = order_within_levels(by_level, edges)

    return {
        "nodes": [{"id": n, "x": lvl.get(n, 0), "y": pos[n], "level": lvl.get(n, 0),
                   "name": titles.get(n, ("", ""))[0], "output": titles.get(n, ("", ""))[1],
                   "loop": n in loop} for n in nodes],
        "edges": edges,
        "names": NAME,
        "legend": [{"kind": k, "text": t} for k, t in [
            ("data", "数据流：搬内容，下游消费它，不改变下一步做谁"),
            ("flow", "工作流：搬决策，下游因它被触发或改变走向"),
            ("open", "待定 ？：既是内容又是决策，勿据此推导开发顺序")]],
    }


