   <tr><td class=k>上游 1 跳</td><td>${hop(up,1).join(' ')||'—'}</td></tr>
   <tr><td class=k>上游 2 跳</td><td>${hop(up,2).join(' ')||'—'}</td></tr>
   <tr><td class=k>下游 1 跳</td><td>${hop(down,1).join(' ')||'—'}</td></tr>
   <tr><td class=k>下游 2 跳</td><td>${hop(down,2).join(' ')||'—'}</td></tr>
   <tr><td class=k>聚焦合计</td><td>${Object.keys(all).length-1} 个节点</td></tr>
   </table>${n.loop?`<div id=warn>⟳ 该节点在数据环内，须与同环切片一起设计或先钉接口</div>`:''}
   <div style="margin-top:8px;color:#94A3B8;font-size:11px">${D.legend.map(l=>`<span class=sw style="border-color:${COL[l.kind]};border-top-style:${l.kind==='data'?'solid':'dashed'}"></span>${l.text}`).join('<br>')}</div>`;
}

document.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{dir=b.dataset.d;
  document.querySelectorAll('[data-d]').forEach(x=>x.classList.toggle('on',x===b));draw();});
document.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>{depth=+b.dataset.k;
  document.querySelectorAll('[data-k]').forEach(x=>x.classList.toggle('on',x===b));draw();});
document.querySelectorAll('[data-c]').forEach(b=>b.onchange=()=>{on[b.dataset.c]=b.checked?1:0;draw();});
document.getElementById('reset').onclick=()=>{focus=null;tx=70;ty=80;sc=1;info();draw();};
svg.addEventListener('click',()=>{if(focus){focus=null;info();draw();}});
addEventListener('keydown',e=>{if(e.key==='Escape'&&focus){focus=null;info();draw();}});
let drag=null;
svg.onmousedown=e=>{drag=[e.clientX-tx,e.clientY-ty];svg.style.cursor='grabbing';};
addEventListener('mouseup',()=>{drag=null;svg.style.cursor='grab';});
addEventListener('mousemove',e=>{if(drag){tx=e.clientX-drag[0];ty=e.clientY-drag[1];draw();}});
svg.addEventListener('wheel',e=>{e.preventDefault();sc=Math.min(2.5,Math.max(.3,sc*(e.deltaY<0?1.12:.9)));draw();},{passive:false});
addEventListener('resize',draw);
draw();
</script></body></html>
"""


def render() -> str:
    return (HTML.replace("__DATA__", json.dumps(build(), ensure_ascii=False))
                .replace("__SX__", str(SX)).replace("__SY__", str(SY))
                .replace("__W__", str(W)).replace("__H__", str(H)))


def main() -> int:
    ap = argparse.ArgumentParser(description="从 .mmd 生成可交互切片依赖图")
    ap.add_argument("--check", action="store_true", help="只检查产物是否过期，不写文件")
    ap.add_argument("--open", dest="open_it", action="store_true", help="生成后用默认浏览器打开")
    args = ap.parse_args()

    html = render()
    if args.check:
        if not OUT.exists() or OUT.read_text(encoding="utf-8") != html:
            print("epi-dev-slices-graph.html 已过期，重跑 tools/gen_slices_graph.py")
            return 1
        print("graph html up to date")
        return 0
    OUT.write_text(html, encoding="utf-8")
    data = json.loads(re.search(r"const D = (\{.*?\});\n", html, re.S).group(1))
    print(f"{OUT.name}: {len(data['nodes'])} 节点 / {len(data['edges'])} 边 "
          f"（数据 {sum(1 for e in data['edges'] if e['kind'] == 'data')} · "
          f"工作 {sum(1 for e in data['edges'] if e['kind'] == 'flow')} · "
          f"待定 {sum(1 for e in data['edges'] if e['kind'] == 'open')}）")
    if args.open_it:
        os.startfile(str(OUT)) if hasattr(os, "startfile") else os.system(f'xdg-open "{OUT}"')
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Standard-Mermaid parser: no knowledge of any particular diagram.

Recognises the elements that are part of Mermaid's own syntax - flowchart
declarations, node definitions with labels, subgraphs, edges with optional
labels, `linkStyle` / `classDef` / `style` statements, `%%` comments - and turns
them into plain data. Semantics (what a colour means, which edges drive layout)
live in a rules file, not here.

Two directives are understood, both written as ordinary Mermaid comments so the
file still renders unchanged:

    %% @legend <subgraphId>      exclude that subgraph and its edges from the graph
    %% @no-layout <nodeId>       keep the node, but never use it to derive levels

Anything that looks like an edge but cannot be parsed is reported, never skipped
silently.
"""

import re
from dataclasses import dataclass, field

COMMENT = re.compile(r"^\s*%%(?P<text>.*)$")
DIRECTIVE = re.compile(r"^\s*%%\s*@(?P<name>[\w-]+)(?P<args>.*)$")
ARROW = re.compile(r"(-\.->|-\.->|-->|---|==>|===|<->|<=>|-\.-|-{2,}|={2,})")
NODE_DEF = re.compile(r"^(?P<id>[A-Za-z0-9_][\w-]*)"
                      r"(?P<label>\[[^\]]*\]|\([^)]*\)|\{[^}]*\})?$")
SUBGRAPH = re.compile(r"^\s*subgraph\s+(?P<id>[\w-]+)(?:\[(?P<title>[^\]]*)\]|\s+(?P<title2>.+?))?\s*$")
LINK_STYLE = re.compile(r"^\s*linkStyle\s+(?P<idx>\d+)|default)\b(?P<rest>.*)$")
STYLE_STMT = re.compile(r"^\s*(classDef|style|click|class)\s+")
DECL = re.compile(r"^\s*(flowchart|graph)\s+")


@dataclass
class Node:
    id: str
    label: str = ""
    subgraph: str = ""


@dataclass
class Edge:
    src: str
    dst: str
    arrow: str
    label: str = ""
    line: int = 0
    src_label: str = ""
    dst_label: str = ""


@dataclass
class MermaidDoc:
    nodes: dict = field(default_factory=dict)
    edges: list = field(default_factory=list)          # declaration order == linkStyle index
    link_styles: dict = field(default_factory=dict)    # index -> {stroke, dash, width}
    subgraphs: dict = field(default_factory=dict)
    directives: list = field(default_factory=list)
    problems: list = field(default_factory=list)

    def legend_ids(self):
        return {a.strip() for name, a, _ in self.directives if name == "legend"}

    def no_layout_ids(self):
        return {a.strip() for name, a, _ in self.directives if name == "no-layout"}

    def graph_edges(self):
        legend = self.legend_ids()
        return [e for e in self.edges
                if not _in_legend(e.src, legend) and not _in_legend(e.dst, legend)]


def _in_legend(node_id, legend):
    return any(node_id == g or node_id.startswith(g) for g in legend)


def _split_node(token):
    m = NODE_DEF.match(token.strip())
    if not m:
        return None, None
    raw = m.group("label") or ""
    return m.group("id"), raw[1:-1].strip() if raw else ""


def _props(text):
    out = {}
    for part in text.split(","):
        if ":" in part:
            k, v = part.split(":", 1)
            out[k.strip().lower()] = v.strip()
    return out


def parse(text: str) -> MermaidDoc:
    doc = MermaidDoc()
    stack = []
    for no, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line:
            continue
        d = DIRECTIVE.match(line)
        if d:
            doc.directives.append((d.group("name"), d.group("args"), no))
            continue
        if COMMENT.match(line):
            continue
        if DECL.match(line):
            continue
        if line == "end":
            if stack:
                stack.pop()
            continue
        sg = SUBGRAPH.match(line)
        if sg:
            title = sg.group("title") or sg.group("title2") or sg.group("id")
            doc.subgraphs[sg.group("id")] = title.strip()
            stack.append(sg.group("id"))
            continue
        if STYLE_STMT.match(line):
            continue

        m = re.match(r"^\s*linkStyle\s+(?:(\d+)|default)\b(.*)$", line)
        if m:
            key = m.group(1) if m.group(1) is not None else "default"
            p = _props(m.group(2))
            doc.link_styles[key] = {
                "stroke": (p.get("stroke") or "").lower(),
                "dash": "dasharray" in p,
                "width": p.get("stroke-width", ""),
            }
            continue

        if ARROW.search(line) is None:
            node_id, label = _split_node(line)
            if node_id:
                doc.nodes.setdefault(node_id, Node(node_id, label, stack[-1] if stack else ""))
                if label and not doc.nodes[node_id].label:
                    doc.nodes[node_id].label = label
            else:
                doc.problems.append((no, raw))
            continue

        parts = list(ARROW.finditer(line))
        if len(parts) != 1:
            doc.problems.append((no, raw))
            continue
        arrow = parts[0]
        left, right = line[:arrow.start()].strip(), line[arrow.end():].strip()
        label = ""
        m = re.match(r"^\|\s*(.*?)\s*\|\s*(.*)$", right)
        if m:
            label, right = m.group(1), m.group(2)
        else:
            m = re.match(r"^--\s*(.*?)\s*-->\s*(.*)$", line[arrow.start():])
            if m:
                label, right = m.group(1), m.group(2)
        src, src_label = _split_node(left)
        dst, dst_label = _split_node(right)
        if not src or not dst:
            doc.problems.append((no, raw))
            continue
        for nid, nlabel in ((src, src_label), (dst, dst_label)):
            n = doc.nodes.setdefault(nid, Node(nid, nlabel, stack[-1] if stack else ""))
            if nlabel and not n.label:
                n.label = nlabel
        doc.edges.append(Edge(src, dst, arrow.group(1), label, no, src_label, dst_label))
    return doc


def style_for(doc: MermaidDoc, index: int):
    """linkStyle for the i-th link, falling back to `linkStyle default`."""
    return doc.link_styles.get(index) or doc.link_styles.get("default") or {}

