def classify(doc, rules):
    """Attach a relation class to every non-legend edge."""
    unknown, out = [], []
    for i, e in enumerate(doc.edges):
        style = mermaid_doc.style_for(doc, i)
        key = (style.get("stroke", "").lower(), style.get("dash", False))
        spec = rules["_by_style"].get(key)
        if spec is None:
