                unknown.append(f"line {e.line}: {e.src} -> {e.dst} "
                               f"stroke={key[0] or '无'} dash={key[1]}")
        out.append({**e.__dict__, "index": i, "kind": spec["class"],
                    "stroke": spec.get("stroke") or key[0], "dash": bool(spec["dash"])})
    if unknown:
        raise SystemExit("配色未在 graph-rules.json 的 palette 中登记：\n  " + "\n  ".join(unknown))
    return out


# --------------------------------------------------------------------------- #
# layout
# --------------------------------------------------------------------------- #
def levels(edges, ordering_classes, skip_nodes):
    data = [(e["src"], e["dst"]) for e in edges
            if e["kind"] in ordering_classes and e["src"] not in skip_nodes and e["dst"] not in skip_nodes]
    adj = collections.defaultdict(set)
    for a, b in data:
        adj[a].add(b)
    nodes = {a for a, _ in data} | {b for _, b in data}

    index, low, stack, onstack, comps = {}, {}, [], set(), []
    for root in sorted(nodes):
        if root in index:
            continue
        work = [(root, iter(adj[root]))]
        index[root] = low[root] = len(index)
        stack.append(root)
        onstack.add(root)
        while work:
            v, it = work[-1]
            moved = False
            for w in it:
                if w not in index:
                    index[w] = low[w] = len(index)
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, iter(adj[w])))
                    moved = True
                    break
                if w in onstack:
                    low[v] = min(low[v], index[w])
            if moved:
                continue
            work.pop()
            if work:
                low[work[-1][0]] = min(low[work[-1][0]], low[v])
            if low[v] == index[v]:
                comp = []
                while True:
                    w = stack.pop()
                    onstack.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                comps.append(comp)

    comp_of = {v: i for i, c in enumerate(comps) for v in c}
    dag, indeg = collections.defaultdict(set), collections.Counter()
    for a, b in data:
        u, v = comp_of[a], comp_of[b]
        if u != v and v not in dag[u]:
            dag[u].add(v)
            indeg[v] += 1
    lvl = [0] * len(comps)
    q = [i for i in range(len(comps)) if indeg[i] == 0]
    while q:
        u = q.pop(0)
        for v in sorted(dag[u]):
            lvl[v] = max(lvl[v], lvl[u] + 1)
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    size = collections.Counter(comp_of.values())
    return ({v: lvl[comp_of[v]] for v in nodes},
            {v for v, i in comp_of.items() if size[i] > 1})


def order_within_levels(by_level, edges, sweeps):
    levels_sorted = sorted(by_level)
    pos = {n: i for l in levels_sorted for i, n in enumerate(by_level[l])}
    up, down = collections.defaultdict(list), collections.defaultdict(list)
    for e in edges:
        down[e["src"]].append(e["dst"])
        up[e["dst"]].append(e["src"])

    def sweep(order, neighbours):
        for l in order:
            members = set(by_level[l])

            def key(n):
                refs = [pos[m] for m in neighbours[n] if m in pos and m not in members]
                return (sum(refs) / len(refs) if refs else pos[n], n)

            by_level[l].sort(key=key)
            for i, n in enumerate(by_level[l]):
                pos[n] = i

    for _ in range(max(1, sweeps)):
        sweep(levels_sorted[1:], up)
        sweep(list(reversed(levels_sorted))[:-1], down)
    return pos


# --------------------------------------------------------------------------- #
# node metadata, looked up by table header names rather than by id pattern
# --------------------------------------------------------------------------- #
def node_info(md_path: Path, spec):
    if not spec or not md_path.exists():
        return {}
    lines = md_path.read_text(encoding="utf-8").splitlines()
    header = None
    cols = {}
    info = {}
    for ln in lines:
        if not ln.startswith("|"):
            continue
        cells = [c.strip() for c in ln.strip().strip("|").split("|")]
        if header is None:
            if spec["key_column"] in cells:
                header = cells
                cols = {i: target for name, target in spec["columns"].items()
                        if name in cells for i, c in enumerate(cells) if c == name}
            continue
        if set("".join(cells)) <= set("-: "):
            continue
        if len(cells) < len(header):
            continue
        key = cells[header.index(spec["key_column"])]
        if key:
            info[key] = {target: cells[i] for i, target in cols.items()}
        elif len([c for c in cells if c]) == 0:
            header = None
    return info


def build(config_path: Path):
    cfg = json.loads(config_path.read_text(encoding="utf-8"))
    base = config_path.parent
    rules = load_rules((base / cfg["rules"]).resolve())
    mmd = (base / cfg["mmd"]).resolve()
    if not mmd.exists():
        raise SystemExit(f"找不到 {mmd}")
    doc = mermaid_doc.parse(mmd.read_text(encoding="utf-8"))
    if doc.problems:
        raise SystemExit("这些行看起来是边但解析失败，请改成标准写法：\n"
                         + "\n".join(f"  line {n}: {t}" for n, t in doc.problems))

    edges = classify(doc.graph_edges(), rules) if not doc.legend_ids() else []
    if not edges:
        legend = doc.legend_ids()
        edges = classify([e for e in
                          [type(e) for e in ()]] or [], rules)  # placeholder, replaced below
    return cfg, rules, doc, edges


