    for l in by_level:
        by_level[l].sort()
    pos = order_within_levels(by_level, edges, layout.get("sweeps", 4))

    present = []
    for p in rules["palette"]:
        if any(e["kind"] == p["class"] for e in edges):
            present.append({"kind": p["class"], "title": p["title"], "desc": p["desc"],
