                      "name": meta.get("name", "") or (doc.nodes[n].label if n in doc.nodes else ""),
                      "extra": {k: v for k, v in meta.items() if k != "name"},
                      "loop": n in loop})
    return cfg, rules, {
        "title": cfg.get("title", mmd.stem),
        "nodes": nodes,
        "edges": [{"s": e["src"], "t": e["dst"], "label": e["label"], "kind": e["kind"]}
