D.edges.forEach(e=>{(out[e.s]=out[e.s]||[]).push(e);(inn[e.t]=inn[e.t]||[]).push(e);});
const esc=s=>String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));

document.getElementById('filters').innerHTML = D.legend.map(l=>
