"""Guard the slice overview: style indices, edge taxonomy, rules coverage, artefacts.

Two historical failures are pinned here.

1. The diagram carried 133 hand-written `linkStyle` lines for 82 links. 50 indices
   were assigned twice, the last assignment won, and 37 solid edges rendered
   orange. Nothing failed - the picture just lied.

2. It mixed three relations (development order, data flow, control flow) into two
   line styles, which forced 13 duplicate edges and left a third of the edges
   mis-styled.

Colours and their meaning come from agent-design/tools/graph-rules.json - the
tests read that file rather than repeating the palette, so the rules stay the
single source of truth.
"""

import collections
import json
import re
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
DESIGN = ROOT / "agent-design"
MMD = DESIGN / "epi-dev-slices-overview.mmd"
MD = DESIGN / "epi-dev-slices-overview.md"
RULES = DESIGN / "tools" / "graph-rules.json"
GENERATOR = DESIGN / "tools" / "gen_interactive_graph.py"
GRAPH_HTML = DESIGN / "epi-dev-slices-graph.html"

# The agent loop is a genuine data cycle: context -> task list -> state machine
# -> current phase back into context. Any other data cycle means a decision was
# smuggled into a data pipe.
DECLARED_DATA_CYCLES = [frozenset({"S17", "S18", "S19"})]

LINK = re.compile(r"^\s*(?!\)\s*$)(\S.*?)\s*(-->|-\.->)\s*(?:\|([^|]*)\|)?\s*(\S.*?)\s*$")
STYLE = re.compile(r"^\s*linkStyle\s+(\d+)\s+stroke:(#[0-9A-Fa-f]{6})")


@pytest.fixture(scope="module")
def rules():
    return json.loads(RULES.read_text(encoding="utf-8"))


@pytest.fixture(scope="module")
def lines() -> list[str]:
    return MMD.read_text(encoding="utf-8").splitlines()


def links(lines):
    out = []
    for line in lines:
        if line.strip().startswith("%%"):
            continue
        m = LINK.match(line)
        if m:
            out.append((m.group(1).split("[", 1)[0], (m.group(3) or "").strip(),
                        m.group(4), m.group(2)))
    return out


def style_map(lines):
    styles = {}
    for line in lines:
        m = STYLE.match(line.strip())
        if m:
            styles[int(m.group(1))] = m.group(2).lower()
    return styles


def palette_index(rules):
    return {(p["stroke"].lower(), bool(p["dash"])): p for p in rules["palette"]}


def classify(lines, rules):
    """Edge class exactly as the generator sees it: colour + Mermaid arrow."""
    styles, pal = style_map(lines), palette_index(rules)
    legend_ids = {ln.split("@legend", 1)[1].split()[0]
                  for ln in lines if "@legend" in ln and ln.strip().startswith("%%")}
    legend_nodes = {a.split("[", 1)[0] for a, _l, _b, _ar in links(lines)
                    if a.split("[", 1)[0] in {"LGS", "LRS", "LPU"}}
    # legend membership is asserted elsewhere; here we only need to skip those links
    out = []
    for i, (a, label, b, arrow) in enumerate(links(lines)):
        spec = pal.get((styles.get(i, ""), arrow == "-.->"))
        out.append((a, label, b, arrow, spec))
    return out, legend_nodes, legend_ids


def test_no_duplicate_linkstyle_index(lines):
    seen, dup = set(), []
    for line in lines:
        m = STYLE.match(line.strip())
        if m:
            if m.group(1) in seen:
                dup.append(m.group(1))
            seen.add(m.group(1))
    assert not dup, f"linkStyle 索引被重复赋值，后者覆盖前者：{dup}"


def test_every_link_is_styled(lines):
    styles = style_map(lines)
    missing = [i for i in range(len(links(lines))) if i not in styles]
    assert not missing, f"{len(missing)} 条 link 没有显式配色，会退回 default：{missing}"


def test_colours_are_registered_in_the_rules(rules, lines):
    pal = palette_index(rules)
    unknown = {c for c in style_map(lines).values() if not any(c == k[0] for k in pal)}
    assert not unknown, f"配色未登记在 graph-rules.json 的 palette 中：{sorted(unknown)}"


def test_colour_and_arrow_agree(lines, rules):
    bad = []
    for a, _label, _b, arrow, spec in classify(lines, rules)[0]:
        if spec is None:
            bad.append((a, "配色/箭头组合不在规则里"))
        elif spec["class"] == "data" and arrow != "-->":
            bad.append((a, "数据流必须是实线"))
        elif spec["class"] != "data" and arrow != "-.->":
            bad.append((a, f"{spec['title']}必须是虚线"))
    assert not bad, f"配色与线型不符：{bad}"


def test_uncertain_edges_are_marked_with_question(lines, rules):
    edges = classify(lines, rules)[0]
    unmarked = [f"{a}->{b}:{label}" for a, label, b, _ar, s in edges
                if s and s["class"] == "open" and not label.startswith("？")]
    assert not unmarked, f"待定边必须以 ？ 开头，否则读者会当成已裁定：{unmarked}"
    mislabelled = [f"{a}->{b}:{label}" for a, label, b, _ar, s in edges
                   if label.startswith("？") and (s is None or s["class"] != "open")]
    assert not mislabelled, f"带 ？ 但不是待定类别：{mislabelled}"


def test_no_duplicate_relations(lines, rules):
    seen = collections.defaultdict(list)
    for a, label, b, _arrow, spec in classify(lines, rules)[0]:
        if spec is not None:
            seen[(a, b, spec["class"])].append(label)
    dup = {k: v for k, v in seen.items() if len(v) > 1}
    assert not dup, f"同一关系画了多次：{dup}"


def test_data_flow_cycles_are_declared(lines, rules):
    adj = collections.defaultdict(set)
    for a, _label, b, _arrow, spec in classify(lines, rules)[0]:
        if spec and spec.get("ordering"):
            adj[a].add(b)
    nodes = set(adj) | {b for vs in adj.values() for b in vs}

    index, low, stack, onstack, comps = {}, {}, [], set(), []
    for root in sorted(nodes):
        if root in index:
            continue
        work = [(root, iter(adj[root]))]
        index[root] = low[root] = len(index)
        stack.append(root)
        onstack.add(root)
        while work:
            v, it = work[-1]
            moved = False
            for w in it:
                if w not in index:
                    index[w] = low[w] = len(index)
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, iter(adj[w])))
                    moved = True
                    break
                if w in onstack:
                    low[v] = min(low[v], index[w])
            if moved:
                continue
            work.pop()
            if work:
                low[work[-1][0]] = min(low[work[-1][0]], low[v])
            if low[v] == index[v]:
                comp = []
                while True:
                    w = stack.pop()
                    onstack.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                comps.append(frozenset(comp))

    found = sorted((c for c in comps if len(c) > 1), key=sorted)
    assert found == sorted(DECLARED_DATA_CYCLES, key=sorted), (
        "排序类别出现未声明的环。已声明 "
        f"{sorted(map(sorted, DECLARED_DATA_CYCLES))}，实际 {sorted(map(sorted, found))}。"
        "环意味着有人把决策塞进了数据管道，或者该边的类别需要重新裁定。")


def test_legend_is_declared_not_hardcoded(lines):
    assert any("@legend" in ln for ln in lines), (
        "图例必须用 `%% @legend <子图id>` 声明，转换工具据此排除")
    assert any("subgraph Legend" in ln for ln in lines), "图例子图缺失"


def test_markdown_block_matches_standalone_file():
    block = re.search(r"```mermaid\n(.*?)\n```", MD.read_text(encoding="utf-8"), re.S).group(1)
    assert block.strip() == MMD.read_text(encoding="utf-8").strip(), (
        "epi-dev-slices-overview.md 内嵌的图与 .mmd 不一致，改图要同时改两处")


def test_interactive_html_is_up_to_date():
    if not GRAPH_HTML.exists():
        raise AssertionError("交互图未生成，跑 tools/gen_interactive_graph.py")
    r = subprocess.run([sys.executable, str(GENERATOR), "--check"],
                       capture_output=True, text=True, cwd=str(DESIGN))
    assert r.returncode == 0, f"交互图已过期：\n{r.stdout}{r.stderr}"

