def count_crossings(by_level, pos, edges, sx=1.0, sy=1.0):
    """Visible crossings, not just same-column-pair inversions.

    Each forward edge is treated as a straight run from its source column to its
    target column; two edges count as crossing when their column intervals
    overlap and their vertical order flips inside that overlap. Long edges that
    cut across several columns therefore cost what they actually cost.
    """
    layer = {n: l for l, ns in by_level.items() for n in ns}
    segs = []
    for e in edges:
        a, b = e["src"], e["dst"]
        la, lb = layer.get(a, 0), layer.get(b, 0)
        if la >= lb:
            continue
        segs.append((la * sx + pos[a] * sy, lb * sx + pos[b] * sy))

    def y_at(s, x):
        x1, x2 = s
        if x2 == x1:
            return x2
        return x1 + (x2 - x1) * (x - x1) / (x2 - x1)

    total = 0
    for (a1, b1), (a2, b2) in itertools.combinations(segs, 2):
        lo, hi = max(a1, a2), min(b1, b2)          # overlap in x
        if hi - lo <= 1e-9:
            continue
        d_lo = y_at((a1, b1), lo) - y_at((a2, b2), lo)
        d_hi = y_at((a1, b1), hi) - y_at((a2, b2), hi)
        if d_lo * d_hi < 0:
            total += 1
    return total

