// BFS distances. Returns {node: hops} from start following one direction.
function reach(start,direction){
  const seen={[start]:0},q=[[start,0]];
  while(q.length){
    const [n,d]=q.shift(); if(d>=depth) continue;
    const cand=direction==='up'?(inn[n]||[]).map(e=>[e.s,e]):(out[n]||[]).map(e=>[e.t,e]);
    for(const [m,e] of cand){ if(!on[e.kind]) continue;
      if(seen[m]===undefined){seen[m]=d+1;q.push([m,d+1]);} }
  }
  return seen;
}
// An edge belongs to the focus only if it lies ON a path out of, or into, the
// focus node: source reachable for downstream edges, target reachable for
// upstream ones. Both-ends-reachable would also light up sibling-to-sibling edges.
function visibleEdges(){
  if(!focus) return null;
  const down=reach(focus,'down'), up=reach(focus,'up'), vis=new Set(), nodes=new Set([focus]);
  Object.keys(down).forEach(n=>nodes.add(n)); Object.keys(up).forEach(n=>nodes.add(n));
  D.edges.forEach((e,i)=>{
    if(!on[e.kind]) return;
    if(dir!=='up'   && down[e.s]!==undefined && down[e.s]<depth) vis.add(i);
    if(dir!=='down' && up[e.t]!==undefined   && up[e.t]<depth)   vis.add(i);
  });
  return {vis,nodes};
}
const el=(t,a)=>{const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);return e;};
function pathOf(pts){
  if(pts.length<3){const [p,q]=pts,c=(p[0]+q[0])/2;return `M${p[0]},${p[1]} C${c},${p[1]} ${c},${q[1]} ${q[0]},${q[1]}`;}
  let d=`M${pts[0][0]},${pts[0][1]}`;
  for(let i=1;i<pts.length;i++){
    const p=pts[i-1],q=pts[i],mx=(p[0]+q[0])/2;
    d+=Math.abs(q[1]-p[1])<1?` L${q[0]},${q[1]}`:` C${mx},${p[1]} ${mx},${q[1]} ${q[0]},${q[1]}`;
  }
  return d;
}

function draw(){
  svg.innerHTML='';
  const g=el('g',{transform:`translate(${tx},${ty}) scale(${sc})`}); svg.appendChild(g);
  const V=visibleEdges();
  const maxLv=Math.max(...D.nodes.map(n=>n.level));
  for(let l=0;l<=maxLv;l++) g.appendChild(el('text',{x:l*250+BX.w/2,y:18,class:'lv'})).textContent='L'+l;

  D.edges.forEach((e,i)=>{
    if(!on[e.kind]) return;
    const cls=V?(V.vis.has(i)?(e.back?' soft':''):' dim'):(e.back?' soft':'');
    g.appendChild(el('path',{d:pathOf(e.pts),fill:'none',class:cls.trim(),
      stroke:COL[e.kind],'stroke-width':e.kind==='open'?3:1.8,
      'marker-end':`url(#a${e.kind})`,'stroke-dasharray':DASH[e.kind]?'7 4':''}));
  });
  if(showLbl) D.edges.forEach((e,i)=>{
    if(!on[e.kind]||(V&&!V.vis.has(i))) return;
    const t=el('text',{x:e.lx,y:e.ly+3.5,'text-anchor':'middle',class:'lbl'+(V&&!V.vis.has(i)?' dim':'')});
    t.textContent=e.label; g.appendChild(t);
  });

  D.nodes.forEach(n=>{
