    const gg=el('g',{class:'node'+(dim?' dim':''),transform:`translate(${n.x},${n.y})`});
    gg.appendChild(el('rect',{width:n.w,height:n.h,rx:7,fill:focus===n.id?'#DBEAFE':'#fff',
