        if abs(px - x) <= hw + pad and abs(py - y) <= hh + pad:
            return True
    return False


def place_labels_free(labels, segs, rects):
    """Put every label in nearby empty space instead of on top of its line.

    Candidates are sampled along the edge itself plus small offsets; the cheapest
    candidate wins, where cost counts crossed lines first, then distance from the
    edge midpoint. Overlapping another label or a node is prohibitive.
    """
    hh = LABEL_H / 2
    segs = [s for s in segs]
    placed = []
    for lab in labels:
        cands = [(lab["ax"], lab["ay"])]
        for t in (0.35, 0.5, 0.65):
            x, y = lab["at"](t)
            for dx in (0, 22, -22, 44, -44):
                for dy in (0, -13, 13, -26, 26):
                    cands.append((x + dx, y + dy))
        scored = []
        for n, (cx, cy) in enumerate(cands):
            hw = lab["w"] / 2
            cost = 0
            for s in segs:
                if _box_hits_segment(cx, cy, hw, hh, s):
                    cost += 100
                    if cost > 400:
                        break
            for rx, ry, rw, rh in rects:
                if abs(cx - rx) < hw + rw / 2 and abs(cy - ry) < hh + rh / 2:
                    cost += 1000
            for p in placed:
                if abs(cx - p["lx"]) < hw + p["w"] / 2 + 4 and abs(cy - p["ly"]) < LABEL_H:
                    cost += 1000
            cost += abs(cx - lab["ax"]) * 0.02 + abs(cy - lab["ay"]) * 0.05
            scored.append((cost, cx, cy))
        scored.sort()
        _, cx, cy = scored[0]
        lab["lx"], lab["ly"] = cx, cy
        lab["cost"] = round(scored[0][0])
        placed.append(lab)
    return labels


